import { expect, test } from "@playwright/test";

test("Atlas shortcuts help supports pointer and keyboard flows", async ({ page }) => {
  await page.goto("/?z=1.60&mapLat=20.000&mapLng=0.000");
  const trigger = page.getByTestId("atlas-shortcuts-trigger");
  await expect(trigger).toBeVisible();
  await expect(trigger).toHaveAccessibleName(/keyboard shortcuts|shortcuts help/i);

  await trigger.click();
  const dialog = page.getByRole("dialog", { name: /keyboard shortcuts/i });
  await expect(dialog).toBeVisible();
  await expect(dialog).toContainText(/escape/i);
  await page.keyboard.press("Escape");
  await expect(dialog).toBeHidden();
  await expect(trigger).toBeFocused();

  await page.keyboard.press("?");
  await expect(dialog).toBeVisible();
  await page.keyboard.press("Escape");

  const input = page.getByTestId("launcher-input");
  await input.focus();
  await input.fill("?");
  await expect(dialog).toBeHidden();
  await expect(input).toHaveValue("?");
});

test("Atlas shortcuts help remains usable at mobile width", async ({ page }) => {
  await page.setViewportSize({ width: 390, height: 844 });
  await page.goto("/?z=1.60&mapLat=20.000&mapLng=0.000");
  await page.getByTestId("atlas-shortcuts-trigger").click();
  const dialog = page.getByRole("dialog", { name: /keyboard shortcuts/i });
  await expect(dialog).toBeVisible();
  const bounds = await dialog.boundingBox();
  expect(bounds).not.toBeNull();
  expect(bounds!.x).toBeGreaterThanOrEqual(0);
  expect(bounds!.x + bounds!.width).toBeLessThanOrEqual(390);
});
